def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows, cols = len(grid), len(grid[0])
    output_rows = 2 * rows
    output_cols = 2 * cols
    result = [[0] * output_cols for _ in range(output_rows)]

    # Padding values assumed as input[0][0] (though need bounds checking)
    padding = [grid[0][0], grid[0][1] if cols > 1 else grid[0][0]]
    if rows > 1:
        padding[0] = grid[rows-1][0]
        padding[1] = grid[rows-1][1] if cols > 1 else grid[rows-1][0]

    def add_pad(n, val, pad):
        return (val + pad) % n

    def get_source(r, c):
        # Try each formula: r + pad[r], c + pad[c]
        for i in range(2):
            for j in range(2):
                r_fn = add_pad(rows, r, [padding[i], padding[j]][i])
                c_fn = add_pad(cols, c, [padding[i], padding[j]][j])
                if r_fn >= 0 and r_fn < rows and c_fn >= 0 and c_fn < cols:
                    return r_fn, c_fn
        return r % rows, c % cols

    for r in range(output_rows):
        for c in range(output_cols):
            src_r, src_c = get_source(r, c)
            result[r][c] = grid[src_r][src_c]

    return result
